import i18next from "eslint-plugin-i18next";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import tsPlugin from "@typescript-eslint/eslint-plugin";
import tsParser from "@typescript-eslint/parser";

export default [
  {
    ignores: [
      // Generated by tauri-specta at debug-build startup; regenerating it is
      // the fix for anything wrong in here, not editing it.
      "src/bindings.ts",
    ],
  },
  {
    files: ["src/**/*.{ts,tsx}"],
    languageOptions: {
      parser: tsParser,
      parserOptions: {
        ecmaFeatures: {
          jsx: true,
        },
      },
    },
    plugins: {
      i18next,
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
      "@typescript-eslint": tsPlugin,
    },
    rules: {
      // Catch text in JSX that should be translated
      "i18next/no-literal-string": [
        "error",
        {
          markupOnly: true, // Only check JSX content, not all strings
          ignoreAttribute: [
            "className",
            "style",
            "type",
            "id",
            "name",
            "key",
            "data-*",
            "aria-*",
          ], // Ignore common non-translatable attributes
        },
      ],

      // Hooks. `exhaustive-deps` is the reason this plugin is here: the app has
      // ~85 useEffect call sites, and without this rule a stale closure over a
      // manager handle or a settings value is invisible until it misbehaves at
      // runtime. `rules-of-hooks` is non-negotiable — violating it corrupts
      // React's internal hook order.
      "react-hooks/rules-of-hooks": "error",
      "react-hooks/exhaustive-deps": "error",

      // Fast-refresh only works if a module's exports are stable across edits.
      // Warn rather than error: some files legitimately co-locate a component
      // with its constants, and that is a DX cost, not a correctness bug.
      "react-refresh/only-export-components": [
        "warn",
        { allowConstantExport: true },
      ],

      // The @typescript-eslint packages were already dependencies but no rule
      // from them was ever enabled. These are the non-type-aware ones that pay
      // for themselves without requiring a typed lint program (which would slow
      // the check-on-every-PR job considerably).
      "@typescript-eslint/no-unused-vars": [
        "error",
        {
          argsIgnorePattern: "^_",
          varsIgnorePattern: "^_",
          caughtErrorsIgnorePattern: "^_",
        },
      ],
      "@typescript-eslint/no-explicit-any": "warn",
      "@typescript-eslint/no-non-null-assertion": "warn",
      "@typescript-eslint/consistent-type-imports": [
        "error",
        { prefer: "type-imports", fixStyle: "inline-type-imports" },
      ],
      "@typescript-eslint/no-empty-object-type": "error",
      "@typescript-eslint/no-unsafe-function-type": "error",

      // Plain-JS footguns that tsc does not catch.
      eqeqeq: ["error", "always", { null: "ignore" }],
      "no-var": "error",
      "prefer-const": "error",
      "no-throw-literal": "error",
    },
  },
  {
    // Tests and mocks legitimately reach for `any` and non-null assertions when
    // building fixtures; holding them to the app's bar produces noise, not bugs.
    files: [
      "src/**/*.test.{ts,tsx}",
      "src/**/__tests__/**/*.{ts,tsx}",
      "src/mocks/**/*.{ts,tsx}",
    ],
    rules: {
      "@typescript-eslint/no-explicit-any": "off",
      "@typescript-eslint/no-non-null-assertion": "off",
      "i18next/no-literal-string": "off",
      "react-refresh/only-export-components": "off",
    },
  },
];
